const estructura = $input.first().json;
const parsear = $('🔍 Parsear Versiones Inglés').item.json;
const wpItem = $('🖼️ WP: Seleccionar Imagen').first().json;
const presentacionId = $('📋 Slides: Copiar Template').item.json.id;

const slideId = estructura.slides?.[0]?.objectId || 'p1';
const pageElements = estructura.slides?.[0]?.pageElements || [];

const wpImageUrl = wpItem?.source_url || null;

// Sanitize text to prevent JSON issues with special characters from AI output
function sanitize(text, maxLen = 120) {
  if (!text) return '';
  return text
    .replace(/[\u201C\u201D\u201E\u201F\u2033\u2036]/g, '"')  // curly double quotes
    .replace(/[\u2018\u2019\u201A\u201B\u2032\u2035]/g, "'")  // curly single quotes
    .replace(/[\n\r]+/g, ' ')                                      // newlines
    .replace(/[^\x20-\x7E\xA0-\xFF]/g, '')                      // non-printable except latin
    .trim()
    .slice(0, maxLen);
}

const titulo = sanitize(parsear.texto_canva_titulo_en || parsear.texto_canva_titulo || 'Post Title', 80);
const subtitulo = sanitize(parsear.texto_canva_subtitulo_en || parsear.texto_canva_subtitulo || 'Post description', 120);

// TEXT requests
const textRequests = [
  { replaceAllText: { containsText: { text: '[titulo_post]', matchCase: true }, replaceText: titulo } },
  { replaceAllText: { containsText: { text: '[descripcion_post]', matchCase: true }, replaceText: subtitulo } }
];

const titleShape = pageElements.find(el =>
  (el.shape?.text?.textElements || []).some(te => (te.textRun?.content || '').includes('[titulo_post]'))
);
if (titleShape) {
  let fontSize = 52;
  if (titulo.length > 15) fontSize = 40;
  if (titulo.length > 22) fontSize = 32;
  if (titulo.length > 30) fontSize = 26;
  textRequests.push({
    updateTextStyle: {
      objectId: titleShape.objectId,
      textRange: { type: 'ALL' },
      style: { fontSize: { magnitude: fontSize, unit: 'PT' } },
      fields: 'fontSize'
    }
  });
}

// IMAGE: use replaceImage on the existing image element in the template
let imageRequest = null;
if (wpImageUrl) {
  const imageElement = pageElements.find(el => el.image !== undefined);
  if (imageElement) {
    imageRequest = {
      requests: [{
        replaceImage: {
          imageObjectId: imageElement.objectId,
          url: wpImageUrl,
          imageReplaceMethod: 'CENTER_CROP'
        }
      }]
    };
  }
}

return [{ json: { presentacionId, textRequests, imageRequest, wpImageUrl, titulo, subtitulo } }];

const parsear = $('🔍 Parsear Versiones Inglés').item.json;
const slides = $('📋 Slides: Copiar Template').item.json;
const drive = $('📁 Subir a Google Drive').item.json;
const thumb = $('🖼️ Slides: Obtener Thumbnail').item.json;

const thumbnailUrl = thumb?.contentUrl || null;
const today = new Date().toISOString().split('T')[0];

const fields = {
  "Tema": parsear.tema_texto || '',
  "Keyword_Principal": parsear.keyword_principal || '',
  "Semana": parsear.tema_semana || 0,
  "Post_ES": (parsear.hook_es || '') + '\n' + (parsear.mensaje_es || '') + '\n' + (parsear.cta_es || ''),
  "Preview_Publicacion": (
    "📸 INSTAGRAM\n━━━━━━━━━━━━━━━━━━━━\n" + (parsear.post_instagram_en || '') +
    "\n\n📘 FACEBOOK\n━━━━━━━━━━━━━━━━━━━━\n" + (parsear.post_facebook_en || '') +
    "\n\n💼 LINKEDIN\n━━━━━━━━━━━━━━━━━━━━\n" + (parsear.post_linkedin_en || '')
  ),
  "Post_Facebook_EN": parsear.post_facebook_en || '',
  "Post_Instagram_EN": parsear.post_instagram_en || '',
  "Titulo_Imagen": parsear.texto_canva_titulo || '',
  "Slides_URL": 'https://docs.google.com/presentation/d/' + slides.id + '/edit',
  "Drive_URL": drive.webViewLink || '',
  "Estado": "Pendiente",
  "Fecha": today
};

// Only add image attachment if thumbnail URL exists
if (thumbnailUrl) {
  fields["Imagen_Post"] = [{ "url": thumbnailUrl }];
}

return [{ json: { records: [{ fields }] } }];

// Seleccionar imagen de WordPress relevante al tema (alt texts en español)
const raw = $input.first().json;
const wpResults = Array.isArray(raw.body) ? raw.body : 
                  (typeof raw.body === 'string' ? JSON.parse(raw.body || '[]') : []);

const WP_BASE = 'https://cratingexpress.com/wp-json/wp/v2/media';
const FIELDS = 'id,source_url,alt_text,title,mime_type';
const MIME_FILTER = 'image/jpeg,image/png';
const ALLOWED_MIME = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/bmp'];
const LOGO_KEYWORDS = ['logo', 'brand', 'icon', 'badge', 'seal', 'stamp', 'cert', 'award', 'photoroom', 'fondo'];

// Usar hook_es y titulo — son específicos del post y en español (como los alt texts)
const parsear = $('🔍 Parsear Versiones Inglés').item.json;
const hookEs = parsear.hook_es || '';
const titulo = parsear.texto_canva_titulo || '';
const subtitulo = parsear.texto_canva_subtitulo || '';

// Extraer palabras clave en español del tema actual
const allText = (hookEs + ' ' + titulo + ' ' + subtitulo).toLowerCase();
const stopWords = ['para','como','con','que','los','las','del','una','por','sus','nos','nuestro','tus','este','esta','son','han','más'];
const themeWords = allText
  .replace(/[^a-záéíóúñü0-9 ]/g, ' ')
  .split(/\s+/)
  .filter(w => w.length > 3 && !stopWords.includes(w))
  .slice(0, 6);

console.log('Theme keywords (ES):', themeWords);
console.log('Hook:', hookEs, '| Título:', titulo);

function isAllowed(item) {
  const mime = (item.mime_type || '').toLowerCase();
  const url = (item.source_url || '').toLowerCase();
  if (!ALLOWED_MIME.some(m => mime.includes(m)) && url.endsWith('.webp')) return false;
  return true;
}

function isLogo(item) {
  const combined = [(item.source_url||''), (item.alt_text||''), (item.title?.rendered||'')].join(' ').toLowerCase();
  return LOGO_KEYWORDS.some(kw => combined.includes(kw));
}

function scoreRelevance(item) {
  const alt = (item.alt_text || item.title?.rendered || '').toLowerCase();
  let score = 0;
  for (const word of themeWords) {
    if (alt.includes(word)) score += 3;
  }
  // Bonus por palabras del hook en español
  const hookWords = hookEs.toLowerCase().split(/\s+/).filter(w => w.length > 3);
  for (const w of hookWords) {
    if (alt.includes(w)) score += 5;
  }
  return score;
}

async function searchImages(searchTerm) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: `${WP_BASE}?search=${encodeURIComponent(searchTerm)}&per_page=20&media_type=image&mime_type=${MIME_FILTER}&_fields=${FIELDS}`,
    });
    return (Array.isArray(resp) ? resp : []).filter(isAllowed).filter(i => !isLogo(i));
  } catch(e) { return []; }
}

// 1. Buscar con hook en español
let candidates = [];
if (hookEs) {
  candidates.push(...await searchImages.call(this, hookEs));
}

// 2. Buscar con las primeras 3 palabras del título
const tituloShort = titulo.split(' ').slice(0, 3).join(' ');
if (tituloShort && tituloShort !== hookEs) {
  const more = await searchImages.call(this, tituloShort);
  const ids = new Set(candidates.map(c => c.id));
  candidates.push(...more.filter(r => !ids.has(r.id)));
}

// 3. Si no hay resultados, buscar con palabras clave individuales
if (candidates.length === 0) {
  for (const word of themeWords.slice(0, 3)) {
    const more = await searchImages.call(this, word);
    const ids = new Set(candidates.map(c => c.id));
    candidates.push(...more.filter(r => !ids.has(r.id)));
    if (candidates.length >= 5) break;
  }
}

console.log('Candidates:', candidates.length);

if (candidates.length > 0) {
  const scored = candidates.map(item => ({ item, score: scoreRelevance(item) }));
  scored.sort((a, b) => b.score - a.score);
  // Elegir aleatoriamente entre el top 5
  const topN = Math.min(5, scored.length);
  const idx = Math.floor(Math.random() * topN);
  const chosen = scored[idx];
  console.log('Chosen (score=' + chosen.score + '):', chosen.item.source_url);
  console.log('Alt:', chosen.item.alt_text);
  return [{ json: { source_url: chosen.item.source_url, alt_text: chosen.item.alt_text || '' } }];
}

// Fallback: últimas 20 imágenes sin logos, aleatorio
try {
  const latest = await this.helpers.httpRequest({
    method: 'GET',
    url: `${WP_BASE}?per_page=20&media_type=image&mime_type=${MIME_FILTER}&_fields=${FIELDS}`,
  });
  const items = (Array.isArray(latest) ? latest : []).filter(isAllowed).filter(i => !isLogo(i));
  if (items.length > 0) {
    const idx = Math.floor(Math.random() * Math.min(10, items.length));
    return [{ json: { source_url: items[idx].source_url, alt_text: '' } }];
  }
} catch(e) {}

return [{ json: { 
  source_url: 'https://cratingexpress.com/wp-content/uploads/2024/08/CE_2_EN-scaled.jpg',
  alt_text: 'Crating Express wooden packaging'
} }];

